class Solution {
    std::vector<int> topoSort(std::unordered_map<int, std::vector<int>>& graph, std::vector<int>& indegree, int count) {
        std::queue<int> q;
        for (int i = 0; i < count; ++i) if (indegree[i] == 0) q.push(i);
        std::vector<int> res;
        while (!q.empty()) {
            int node = q.front();
            q.pop();
            res.push_back(node);
            for (int neighbor : graph[node]) {
                if (--indegree[neighbor] == 0) q.push(neighbor);
            }
        }
        return res.size() == count ? res : std::vector<int>();
    }
