    std::vector<int> sortItems(int n, int m, std::vector<int>& group, std::vector<std::vector<int>>& beforeItems) {
        for (int i = 0; i < n; ++i) {
            if (group[i] == -1) group[i] = m++;
        }

        std::unordered_map<int, std::vector<int>> itemGraph, groupGraph;
        std::vector<int> itemIndegree(n, 0), groupIndegree(m, 0);

        for (int curr = 0; curr < n; ++curr) {
            for (int prev : beforeItems[curr]) {
                itemGraph[prev].push_back(curr);
                itemIndegree[curr]++;
                if (group[prev] != group[curr]) {
                    groupGraph[group[prev]].push_back(group[curr]);
                    groupIndegree[group[curr]]++;
                }
            }
        }

        std::vector<int> itemOrder = topoSort(itemGraph, itemIndegree, n);
        std::vector<int> groupOrder = topoSort(groupGraph, groupIndegree, m);

        if (itemOrder.empty() || groupOrder.empty()) return {};

        std::unordered_map<int, std::vector<int>> groupedItems;
        for (int item : itemOrder) groupedItems[group[item]].push_back(item);

        std::vector<int> ans;
        for (int grp : groupOrder) {
            for (int item : groupedItems[grp]) ans.push_back(item);
        }
        return ans;
    }
};

class Solution {
    java.util.List<Integer> topoSort(java.util.Map<Integer, java.util.List<Integer>> graph, int[] indegree, int count) {
        java.util.Queue<Integer> q = new java.util.LinkedList<>();
        for (int i = 0; i < count; i++) if (indegree[i] == 0) q.add(i);
        java.util.List<Integer> res = new java.util.ArrayList<>();
        while (!q.isEmpty()) {
            int node = q.poll();
            res.add(node);
            for (int neighbor : graph.getOrDefault(node, java.util.List.of())) {
                if (--indegree[neighbor] == 0) q.add(neighbor);
            }
        }
        return res.size() == count ? res : java.util.List.of();
    }

    public int[] sortItems(int n, int m, int[] group, java.util.List<java.util.List<Integer>> beforeItems) {
        for (int i = 0; i < n; i++) {
            if (group[i] == -1) group[i] = m++;
        }

        java.util.Map<Integer, java.util.List<Integer>> itemGraph = new java.util.HashMap<>();
        java.util.Map<Integer, java.util.List<Integer>> groupGraph = new java.util.HashMap<>();
        int[] itemIndegree = new int[n];
        int[] groupIndegree = new int[m];

        for (int curr = 0; curr < n; curr++) {
            for (int prev : beforeItems.get(curr)) {
                itemGraph.computeIfAbsent(prev, k -> new java.util.ArrayList<>()).add(curr);
                itemIndegree[curr]++;
                if (group[prev] != group[curr]) {
                    groupGraph.computeIfAbsent(group[prev], k -> new java.util.ArrayList<>()).add(group[curr]);
                    groupIndegree[group[curr]]++;
                }
            }
        }

        java.util.List<Integer> itemOrder = topoSort(itemGraph, itemIndegree, n);
        java.util.List<Integer> groupOrder = topoSort(groupGraph, groupIndegree, m);

        if (itemOrder.isEmpty() || groupOrder.isEmpty()) return new int[0];

        java.util.Map<Integer, java.util.List<Integer>> grouped = new java.util.HashMap<>();
        for (int item : itemOrder) {
            grouped.computeIfAbsent(group[item], k -> new java.util.ArrayList<>()).add(item);
        }

        int[] ans = new int[n];
        int idx = 0;
        for (int grp : groupOrder) {
            for (int item : grouped.getOrDefault(grp, java.util.List.of())) {
                ans[idx++] = item;
            }
        }
        return ans;
    }
}

var sortItems = function(n, m, group, beforeItems) {
    for (let i = 0; i < n; i++) {
        if (group[i] === -1) group[i] = m++;
    }

    const itemGraph = new Map(), groupGraph = new Map();
    const itemIndegree = new Array(n).fill(0);
    const groupIndegree = new Array(m).fill(0);

    for (let curr = 0; curr < n; curr++) {
        for (const prev of beforeItems[curr]) {
            if (!itemGraph.has(prev)) itemGraph.set(prev, []);
            itemGraph.get(prev).push(curr);
            itemIndegree[curr]++;
            if (group[prev] !== group[curr]) {
                if (!groupGraph.has(group[prev])) groupGraph.set(group[prev], []);
                groupGraph.get(group[prev]).push(group[curr]);
                groupIndegree[group[curr]]++;
            }
        }
    }

    const topoSort = (graph, indegree, count) => {
        const q = [];
        for (let i = 0; i < count; i++) if (indegree[i] === 0) q.push(i);
        const res = [];
        while (q.length > 0) {
            const node = q.shift();
            res.push(node);
            for (const neighbor of graph.get(node) || []) {
                if (--indegree[neighbor] === 0) q.push(neighbor);
            }
        }
        return res.length === count ? res : [];
    };

    const itemOrder = topoSort(itemGraph, itemIndegree, n);
    const groupOrder = topoSort(groupGraph, groupIndegree, m);

    if (itemOrder.length === 0 || groupOrder.length === 0) return [];

    const grouped = new Map();
    for (const item of itemOrder) {
        const grp = group[item];
        if (!grouped.has(grp)) grouped.set(grp, []);
        grouped.get(grp).push(item);
    }

    const ans = [];
    for (const grp of groupOrder) {
        for (const item of grouped.get(grp) || []) {
            ans.push(item);
        }
    }
    return ans;
};
